CREATE MATERIALIZED VIEW order_count_mv AS SELECT COUNT(*) AS cnt FROM orders;
SELECT * FROM order_count_mv; -- Shows count at creation time
INSERT INTO orders (order_id, customer_id, order_date, status) VALUES (999, 1, '2024-12-31', 'placed');
SELECT * FROM order_count_mv; -- Still shows old count!
REFRESH MATERIALIZED VIEW order_count_mv;
SELECT * FROM order_count_mv; -- Now shows new count
